def all_pairs(values):
    return [(values[i], values[j]) for i in range(len(values)) for j in range(i + 1, len(values))]

print(all_pairs([1, 2, 3]))

def pair_sum(values, target):
    left, right = 0, len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return [left, right]
        if total < target:
            left += 1
        else:
            right -= 1

print(pair_sum([1, 2, 4, 7, 11], 9))
